mapper.select:
SELECT record_type,COUNT(*) record_count,0 manager_input_count FROM (
  SELECT 'WORK' record_type FROM work_log WHERE farm_id=#{farmId} AND deleted_at IS NULL AND work_date BETWEEN #{dateFrom} AND #{dateTo}
  UNION ALL SELECT 'PEST_CONTROL' FROM pest_control_log WHERE farm_id=#{farmId} AND deleted_at IS NULL AND apply_date BETWEEN #{dateFrom} AND #{dateTo}
  UNION ALL SELECT 'HARVEST' FROM harvest_log WHERE farm_id=#{farmId} AND deleted_at IS NULL AND harvest_date BETWEEN #{dateFrom} AND #{dateTo}
  UNION ALL SELECT 'SALES' FROM sales_log WHERE farm_id=#{farmId} AND deleted_at IS NULL AND sales_date BETWEEN #{dateFrom} AND #{dateTo}
) r GROUP BY record_type

SELECT LOWER(TRIM(unit)) unit,SUM(quantity) sold_quantity,0 gross_sales_amount FROM harvest_log
WHERE farm_id=#{farmId} AND deleted_at IS NULL AND harvest_date BETWEEN #{dateFrom} AND #{dateTo}
GROUP BY LOWER(TRIM(unit)) ORDER BY unit

SELECT COALESCE(SUM(gross_amount),0) current_gross,COALESCE(SUM(fee_amount),0) current_fee,
  COALESCE(SUM(net_amount),0) current_net,COUNT(*) current_count FROM sales_log
WHERE farm_id=#{farmId} AND deleted_at IS NULL AND sales_date BETWEEN #{dateFrom} AND #{dateTo}

SELECT LOWER(TRIM(unit)) unit,SUM(quantity) sold_quantity,SUM(gross_amount) gross_sales_amount FROM sales_log
WHERE farm_id=#{farmId} AND deleted_at IS NULL AND sales_date BETWEEN #{dateFrom} AND #{dateTo}
GROUP BY LOWER(TRIM(unit)) HAVING SUM(quantity)>0 ORDER BY unit
